import 'dart:developer';import 'dart:math' hide log;import 'package:cloud_firestore/cloud_firestore.dart';import 'package:volleyball_tournament_app/model/player.dart';import '../model/tournament.dart';class FirebaseService {  static final FirebaseFirestore _database = FirebaseFirestore.instance;  Future<List<Player>> getPlayers() async {    List<Player> players = [];    await _database.collection('players').get().then((res) {      if(res.docs.isNotEmpty) {        for(var doc in res.docs) {          if(doc.exists) {            players.add(Player.fromJson(doc.data()));          }        }      }    });    return players;  }  Future<dynamic> addPlayer({required Player player}) async {    final querySnapshot = await _database        .collection('players')        .where('nome', isEqualTo: player.nome)        .get();    if (querySnapshot.docs.isNotEmpty) {      return 'Jogador com o mesmo nome já existe!';    }    final ref = await _database.collection('players').add(player.toJson());    player.id = ref.id;    return await updatePlayerData({"id": player.id}, ref.id);  }  Future<void> removePlayer({required String playerId}) async {    return await _database.collection('players').doc(playerId).delete();  }  Future<void> updatePlayerData(Map<String, dynamic> info, String id) async {    return await _database.collection('players').doc(id).update(info);  }  Future<void> updateTorneioData(Map<String, dynamic> info, String id) async {    return await _database.collection('torneios').doc(id).update(info);  }  Future<void> insertSingle(String key, Map<String, dynamic> value, String id) async {    return await _database.collection('torneios')      .doc(id)      .update({key: FieldValue.arrayUnion([value])});  }  Future<void> removeSingle(String key, Map<String, dynamic> value, String id) async {    return await _database.collection('torneios')      .doc(id)      .update({key: FieldValue.arrayRemove([value])});  }  Future<String> gerarCodigoTorneio() async {    String generateCode() {      final random = Random();      return List.generate(4, (_) => random.nextInt(10)).join();    }    String code = generateCode();    final querySnapshot = await _database      .collection('torneios')      .get();    List<String> codigos = [];    for(var docs in querySnapshot.docs) {      if(docs.exists) {        final data = docs.data();        codigos.add(data["codigo"].toString());      }    }    if(codigos.isNotEmpty) {      while(codigos.contains(code)) {        code = generateCode();      }    }    return code;  }    Future<Map<String, dynamic>?> getTorneioByCode({required String code}) async {    final querySnapshot = await _database        .collection('torneios')        .where('codigo', isEqualTo: code)        .get();    if(querySnapshot.docs.isNotEmpty) {      final torneio = querySnapshot.docs.first.data();      return {"nome": torneio["nomeTorneio"], "mode": torneio["modelo"], "ativo": torneio["ativo"]};    }    return null;  }  Future<String?> getPass({required String nomeDoTorneio}) async {    final querySnapshot = await _database        .collection('torneios')        .where('nomeTorneio', isEqualTo: nomeDoTorneio)        .get();    if(querySnapshot.docs.isNotEmpty) {      final torneio = querySnapshot.docs.first.data();      return torneio["senha"];    }    return null;  }  Future<bool> getActive({required String nomeDoTorneio}) async {    final querySnapshot = await _database        .collection('torneios')        .where('nomeTorneio', isEqualTo: nomeDoTorneio)        .get();    if(querySnapshot.docs.isNotEmpty) {      final torneio = querySnapshot.docs.first.data();      return torneio["ativo"];    }    return false;  }  Future<Tournament?> loadFromBd({required String nomeDoTorneio}) async {    try {      final querySnapshot = await _database          .collection('torneios')          .where('nomeTorneio', isEqualTo: nomeDoTorneio)          .get();      if(querySnapshot.docs.isNotEmpty) {        final torneio = querySnapshot.docs.first.data();        return Tournament.fromJson(torneio);      }      return null;    }catch(e, stack) {      log('Não foi possivel carergar o torneio pelo nome $e', stackTrace: stack);      return null;    }  }    Future<List<Team>> getClassifiedPlayers({required String torneioId}) async {    try{      List<Team> times = [];      final Map<String, List<Player>> timesMap = {};      final querySnapshot = await _database.collection('torneios').doc(torneioId).collection('timesClassificados').get();      if(querySnapshot.docs.isNotEmpty) {        final docs = querySnapshot.docs;        for(var doc in docs) {          final data = doc.data();          final teamId = data['teamId'];          if (teamId != null) {            final player = Player.fromJson(data);            if (!timesMap.containsKey(teamId)) {              timesMap[teamId] = [];            }            timesMap[teamId]!.add(player);          }        }      }      times = timesMap.entries          .map((entry) => Team(id: entry.key, players: entry.value))          .toList();      return times;    }catch(e, stack) {      log('Nao foi possivel recuperar os jogadores classificados: $e', stackTrace: stack);      return [];    }  }  Future<void> addToClassifiedTeams({required String torneioId, required List<Player> players}) async {    for(Player player in players) {      await _database.collection('torneios').doc(torneioId).collection('timesClassificados').add(player.toJson());    }    return;  }  Future<void> disqualifyTeam({required String torneioId, required List<Player> players}) async {    await _database.collection('torneios').doc(torneioId).collection('timesClassificados').get().then((res) async {      if(res.docs.isNotEmpty) {        final docs = res.docs;        final playersIds = players.map((p) => p.id!).toList();        for(var doc in docs) {          final player = Player.fromJson(doc.data());          if(playersIds.contains(player.id!)) {            await _database.collection('torneios').doc(torneioId).collection('timesClassificados').doc(doc.id).delete();          }        }      }    });    return;  }    Future<String?> addTorneio({required Tournament torneio}) async {    try{      final torneioJson = torneio.toJson();      final ref = await _database.collection('torneios').add(torneioJson);      await updateTorneioData({"id": ref.id}, ref.id);      return ref.id;    }catch(e, stack) {      log('NAO FOI POSSIVEL ADICIONAR O TORNEIO $e', stackTrace: stack);      return null;    }  }}